def cantor_numbering(N: int) -> str:
    if N < 1:
        raise ValueError("N must be a positive integer greater than 0")

    level = 1
    while N > level:
        N -= level
        level += 1

    if level % 2 == 0:
        # Even level, fraction is numerator/denominator
        numerator = level - N + 1
        denominator = N
    else:
        # Odd level, fraction is denominator/numerator
        numerator = N
        denominator = level - N + 1

    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product that can be obtained by inserting K multiplication signs into the number string.

    :param num_str: String representing the number.
    :param N: Length of the number string.
    :param K: Number of multiplication signs to insert.
    :return: The maximum product.
    """
    if N == 0 or K == 0 or K >= N:
        return 0

    # Convert the string to a list of integers
    digits = [int(d) for d in num_str]

    # Helper function to split the digits into parts and calculate the product
    def split_and_multiply(parts):
        product = 1
        for part in parts:
            num = int(''.join(map(str, part)))
            if num > 0:
                product *= num
        return product

    # Try all possible ways to insert K multiplication signs
    def backtrack(start, parts):
        if len(parts) == K + 1:
            return split_and_multiply(parts)

        max_product = 0
        for end in range(start + 1, N + 1):
            current_part = digits[start:end]
            if current_part:
                parts.append(current_part)
                max_product = max(max_product, backtrack(end, parts))
                parts.pop()

        return max_product

    return backtrack(0, [])

def max_product(num_str: str, N: int, K: int) -> int:
