        raise ValueError("Invalid input values")

    def split_and_multiply(parts):
        product = 1
        for part in parts:
            if part:
                product *= int(part)
        return product

    def backtrack(start, remaining_k, current_parts):
        if remaining_k == 0:
            current_parts.append(num_str[start:])
            max_product = split_and_multiply(current_parts)
            current_parts.pop()
            return max_product

        max_product = 0
        for i in range(start + 1, N - remaining_k + 2):
            current_parts.append(num_str[start:i])
            max_product = max(max_product, backtrack(i, remaining_k - 1, current_parts))
            current_parts.pop()

        return max_product

    return backtrack(0, K, [])

