def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    # Create a hashmap to store the index of each value in inorder for O(1) lookup
    index_map = {value: index for index, value in enumerate(inorder)}

    def helper(in_start, in_end, post_start, post_end):
        if in_start > in_end or post_start > post_end:
            return ""

        # The last element in the current postorder range is the root
        root_val = postorder[post_end]
        root_index = index_map[root_val]

        # Calculate the size of the left subtree
        left_size = root_index - in_start

        # Recursively construct the left and right subtrees
        left_preorder = helper(in_start, root_index - 1, post_start, post_start + left_size - 1)
        right_preorder = helper(root_index + 1, in_end, post_start + left_size, post_end - 1)

        # Preorder traversal is root followed by left and right preorder traversals
        return root_val + left_preorder + right_preorder

    # Build the preorder traversal using the helper function
    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

def preorder_traversal(inorder: str, postorder: str) -> str:
    def build_tree(inorder, postorder, in_start, in_end, post_start, post_end, index_map):
        if in_start > in_end or post_start > post_end:
            return None

        # The last element in current postorder traversal is the root
        root_val = postorder[post_end]
        root = Node(root_val)

        # Find the index of the root in inorder traversal
        in_root = index_map[root_val]

        # Calculate sizes of left and right subtrees
        left_tree_size = in_root - in_start

        # Recursively build left and right subtrees
        root.left = build_tree(inorder, postorder, in_start, in_root - 1, post_start, post_start + left_tree_size - 1, index_map)
        root.right = build_tree(inorder, postorder, in_root + 1, in_end, post_start + left_tree_size, post_end - 1, index_map)

        return root

    def preorder(node):
        if node is None:
            return ""
        return node.val + preorder(node.left) + preorder(node.right)

    if not inorder or not postorder or len(inorder) != len(postorder):
        return ""

    # Create a hashmap to store value -> index pairs for quick lookup
    index_map = {value: index for index, value in enumerate(inorder)}

    # Build the tree
    n = len(inorder)
    root = build_tree(inorder, postorder, 0, n - 1, 0, n - 1, index_map)

    # Get the preorder traversal of the tree
    return preorder(root)

