def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a DP array where dp[i] is True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: a subset with volume 0 is always possible (empty subset)

    # Iterate over each item
    for volume in volumes:
        # Update the dp array from back to front to avoid using the same item multiple times
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be formed which is less than or equal to V
    max_achievable_volume = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_achievable_volume = i
            break

    # The minimum remaining space is the difference between the box's capacity and the maximum volume that can be formed
    return V - max_achievable_volume

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a list to store whether a certain volume is achievable
    achievable = [False] * (V + 1)
    achievable[0] = True  # Zero volume is always achievable

    # Iterate over each item's volume
    for volume in volumes:
        # Update the achievable list from back to front
        for j in range(V, volume - 1, -1):
            if achievable[j - volume]:
                achievable[j] = True

    # Find the maximum achievable volume that is less than or equal to V
    max_achievable_volume = 0
    for j in range(V, -1, -1):
        if achievable[j]:
            max_achievable_volume = j
            break

    # The minimum remaining space is the total capacity minus the maximum achievable volume
    return V - max_achievable_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
