    n = len(heights)
    if n == 0:
        return 0

    # Initialize arrays to hold the length of the longest increasing subsequence (LIS) and
    # the longest decreasing subsequence (LDS) ending at each position
    lis = [1] * n
    lds = [1] * n

    # Fill LIS array
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Fill LDS array
    for i in range(n-1, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # The length of the longest choir formation for each position i is lis[i] + lds[i] - 1
    # We want to maximize this value to minimize the number of students to leave
    max_choir_length = max(lis[i] + lds[i] - 1 for i in range(n))

    # The minimum number of students to leave is the total number of students minus
    # the length of the longest choir formation
    return n - max_choir_length

