def hanoi_double_iterative(n: int) -> int:
    if n <= 0:
        raise ValueError("The number of disc pairs must be a positive integer.")

    # Base case for 1 pair of discs
    if n == 1:
        return 2

    # Initialize the number of moves for 1 pair of discs
    moves = 2

    # Iteratively calculate the number of moves for n pairs of discs
    for i in range(2, n + 1):
        moves = 3 * moves - 2

    return moves
